/**
 * Componente de Logo Ultra-Limpo
 * Usa mask-image para tratar a logo como um carimbo, eliminando artefatos de pixels nas bordas.
 */
const LogoImage = ({ scrolled, className = "" }: { scrolled?: boolean, className?: string }) => {
  // Se não houver scroll (ou indefinido no footer), queremos a logo branca.
  // Se houver scroll, queremos a logo na cor original ou preta.
  const isWhite = scrolled === false || scrolled === undefined;

  return (
    <div 
      className={`transition-all duration-300 ${className}`}
      style={{
        backgroundColor: isWhite ? '#FFFFFF' : '#2D332D',
        maskImage: `url(${LOGO_URL})`,
        WebkitMaskImage: `url(${LOGO_URL})`,
        maskSize: 'contain',
        WebkitMaskSize: 'contain',
        maskRepeat: 'no-repeat',
        WebkitMaskRepeat: 'no-repeat',
        maskPosition: 'center',
        WebkitMaskPosition: 'center',
      }}
    />
  );
};

